function cardContent(item,article){const links=el('div','card-links');for(const raw of item.links||[]){const a=safeCardLink(raw);if(a)links.append(a);}if(links.children.length)article.append(links);const steps=item.steps||[],files=item.files||[],images=el('div','image-strip');for(const [n,name]of files.entries())if(imageName(name))images.append(imageTile(name,'/phone/card-file?thread='+encodeURIComponent(item.thread)+'&n='+n));if(images.children.length){images.className+=' '+(images.children.length>1?'multiple':'single');article.append(images);}if(!item.body&&!steps.length&&!files.length&&!item.reply)return;const details=el('details','card-details');details.append(el('summary','','Details'));if(item.body)details.append(el('p','',item.body));if(steps.length){const conversation=el('div','card-conversation');if(steps.length>3){const older=el('details','steps');older.append(el('summary','','Show earlier'));for(const step of steps.slice(0,-3))older.append(el('p','',step.text));conversation.append(older);}for(const step of steps.slice(-3))conversation.append(el('p','',step.text));details.append(conversation);}for(const [n,name]of files.entries()){if(imageName(name))continue;const a=el('a','file-link',name);a.href='/phone/card-file?thread='+encodeURIComponent(item.thread)+'&n='+n;a.download=name;a.target='_blank';a.rel='noopener noreferrer';details.append(a);}article.append(details);}
