async function loadSettings(){try{settings=await api('settings');for(const n of document.querySelectorAll('[data-setting]')){n.checked=!!settings.notifications[n.dataset.setting];n.disabled=false;}$('digestTime').value=settings.notifications.digestTime||'08:00';$('digestTime').disabled=!settings.notifications.digest;$('settingsStatus').textContent='';$('enablePush').textContent=settings.subscribed?'Notifications enabled':'Enable notifications';$('enablePush').disabled=!!settings.subscribed;}catch(e){if(e.status!==404)throw e;$('settingsStatus').textContent='Notification settings are not available yet.';document.querySelectorAll('[data-setting]').forEach(n=>n.disabled=true);$('enablePush').disabled=true;}}
