async function enablePush(){if(PREVIEW){toast('Enable notifications in the installed app.');return;}if(!('Notification'in window)||!('PushManager'in window))throw Error('Add Kokuban to your Home Screen first.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not allowed.');const registration=await navigator.serviceWorker.register('/phone/sw.js',{scope:'/phone/'});await navigator.serviceWorker.ready;const {publicKey}=await api('push-key');const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:publicKey});await api('push-subscription',{subscription:subscription.toJSON()});await loadSettings();}
function applyVoiceResult(d,job,result){if(!d.files.some(a=>a.id===job.attachmentId)){job.state='complete';return;}job.state=result.state;job.error=result.error;const transcript=result.refined||result.small;if(!transcript||job.best===transcript.text)return;job.best=transcript.text;const text=(job.base?job.base+'\n':'')+transcript.text;if(d.revision===job.expectedRevision){d.text=text;d.revision++;job.expectedRevision=d.revision;job.manual=false;}else job.manual=true;}
