function setSwipe(w,target){w.target=target;cancelAnimationFrame(w.frame);w.tray.setAttribute('aria-hidden',target===0?'true':'false');w.tray.querySelectorAll('button').forEach(b=>b.tabIndex=target===0?-1:0);if(matchMedia('(prefers-reduced-motion: reduce)').matches){w.offset=target;w.front.style.transform='translateX('+target+'px)';return;}let last=performance.now();const frame=now=>{const dt=Math.min(.025,(now-last)/1000);last=now;const acceleration=600*(target-w.offset)-49*w.velocity;w.velocity+=acceleration*dt;w.offset+=w.velocity*dt;w.front.style.transform='translateX('+w.offset+'px)';if(Math.abs(target-w.offset)>.2||Math.abs(w.velocity)>1)w.frame=requestAnimationFrame(frame);else{w.offset=target;w.velocity=0;w.front.style.transform='translateX('+target+'px)';}};w.frame=requestAnimationFrame(frame);}
function contextMenu(title,actions){document.querySelector('.context-layer')?.remove();const previous=document.activeElement,layer=el('div','context-layer'),menu=el('div','context-menu');layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label',title);menu.append(el('b','',title));const close=()=>{layer.remove();previous?.focus();};for(const action of actions){const b=button(action.label,()=>{close();Promise.resolve().then(action.run).catch(problem);},action.danger?'danger':'');menu.append(b);}menu.append(button('Cancel',close));layer.append(menu);layer.onclick=e=>{if(e.target===layer)close();};layer.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const buttons=[...menu.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.body.append(layer);layer.tabIndex=-1;layer.focus();}
